import {getExercises} from '../domain/model';
import type {Dataset, ExerciseType} from '../domain/types';
import data from './exercises.json';

/** Bundled, attributable exercise catalog. Generated by scripts/catalog/generate.py; never edited by hand. */
export type BodyPart =
  'Chest' | 'Back' | 'Shoulders' | 'Arms' | 'Legs' | 'Core' | 'Cardio' | 'Full body' | 'Other';
export interface CatalogSource {
  kind: 'illustration' | 'instructions' | 'muscles';
  title: string;
  author: string;
  license: string;
  licenseUrl: string;
  url: string;
  changes?: string;
}
export interface CatalogExercise {
  name: string;
  bodyPart: BodyPart;
  equipment: string;
  type: ExerciseType;
  primaryMuscles: string[];
  secondaryMuscles: string[];
  instructions: string[];
  images: {file: string; width: number; height: number}[];
  sources: CatalogSource[];
  history?: boolean | null;
}
export const bodyParts: BodyPart[] = [
  'Chest',
  'Back',
  'Shoulders',
  'Arms',
  'Legs',
  'Core',
  'Cardio',
  'Full body',
  'Other',
];
export const catalog = data as CatalogExercise[];
const byName = new Map(catalog.map((exercise) => [exercise.name, exercise]));
/** Exact-name lookup only: history names are never fuzzy-matched or renamed. */
export function catalogEntry(name: string): CatalogExercise | undefined {
  return byName.get(name);
}

const urls = import.meta.glob<string>('./images/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});
export function imageUrl(file: string): string | undefined {
  return urls[`./images/${file}`];
}

export function bodyPartOf(name: string): BodyPart {
  return catalogEntry(name)?.bodyPart ?? 'Other';
}
/** Recorded history decides the type first; the catalog only fills in for new exercises. */
export function exerciseTypeFor(name: string, dataset: Dataset): ExerciseType | undefined {
  for (const workout of dataset.workouts)
    for (const exercise of workout.exercises) if (exercise.name === name) return exercise.type;
  return catalogEntry(name)?.type;
}
/** Catalog plus every recorded name (custom or historical), exact and unmerged. */
export function allExerciseNames(dataset: Dataset): string[] {
  return [...new Set([...catalog.map((e) => e.name), ...getExercises(dataset)])].sort((a, b) =>
    a.localeCompare(b),
  );
}
